sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    // =========================================================
    // INITIAL PAGE
    // =========================================================

    c.currentPage =
        'dashboard';


    // =========================================================
    // OPEN RECORD VARIABLES
    // =========================================================

    c.showRecordForm =
        false;

    c.selectedRecord =
        null;

    c.formError =
        '';

    c.formSuccess =
        '';

    c.savingRecord =
        false;

    c.notesVisible =
        false;

    c.notesRequired =
        false;


    // =========================================================
    // FILTER OPTIONS
    // =========================================================

    c.useCaseOptions =
        c.data.filterOptions.useCases || [];


    c.priorityOptions =
        c.data.filterOptions.priorities || [];


    // =========================================================
    // ASSIGNMENT FILTERS
    // =========================================================

    c.assignmentFilters = {

        use_case:
            '',

        current_priority:
            ''

    };


    // =========================================================
    // INITIAL ASSIGNMENT LIST
    // =========================================================

    c.filteredAssignmentIds =
        angular.copy(
            c.data.myAssignmentIds
        );


    // =========================================================
    // CHANGE PAGE
    // =========================================================

    c.changePage =
        function(page) {

            c.currentPage =
                page;

            c.closeRecordForm();

        };


    // =========================================================
    // APPLY ASSIGNMENT FILTERS
    // =========================================================

    c.applyAssignmentFilters =
        function() {

            c.filteredAssignmentIds =
                [];


            for (
                var i = 0;
                i < c.data.myAssignmentIds.length;
                i++
            ) {

                var sysId =
                    c.data.myAssignmentIds[i];


                var record =
                    c.data.records[sysId];


                if (!record) {

                    continue;

                }


                // ---------------------------------------------
                // USE CASE FILTER
                // ---------------------------------------------

                if (
                    c.assignmentFilters.use_case &&
                    record.use_case_value !==
                    c.assignmentFilters.use_case
                ) {

                    continue;

                }


                // ---------------------------------------------
                // PRIORITY FILTER
                // ---------------------------------------------

                if (
                    c.assignmentFilters.current_priority &&
                    record.current_priority_value !==
                    c.assignmentFilters.current_priority
                ) {

                    continue;

                }


                c.filteredAssignmentIds.push(
                    sysId
                );

            }

        };


    // =========================================================
    // CLEAR FILTERS
    // =========================================================

    c.clearAssignmentFilters =
        function() {

            c.assignmentFilters.use_case =
                '';

            c.assignmentFilters.current_priority =
                '';

            c.applyAssignmentFilters();

        };


    // =========================================================
    // OPEN RECORD
    //
    // sys_id
    //   ↓
    // data.records
    //   ↓
    // angular.copy
    //   ↓
    // selectedRecord
    //   ↓
    // custom form
    // =========================================================

    c.openRecord =
        function(sysId) {

            c.formError =
                '';

            c.formSuccess =
                '';

            c.savingRecord =
                false;


            var record =
                c.data.records[sysId];


            if (!record) {

                c.formError =
                    'Unable to find the selected record.';

                return;

            }


            c.selectedRecord =
                angular.copy(record);


            if (
                !c.selectedRecord.approval
            ) {

                c.selectedRecord.approval =
                    'requested';

            }


            c.selectedRecord.approval =
                String(
                    c.selectedRecord.approval
                ).toLowerCase();


            c.updateNotesVisibility();


            c.showRecordForm =
                true;

        };


    // =========================================================
    // CLOSE RECORD FORM
    // =========================================================

    c.closeRecordForm =
        function() {

            c.showRecordForm =
                false;

            c.selectedRecord =
                null;

            c.formError =
                '';

            c.formSuccess =
                '';

            c.savingRecord =
                false;

            c.notesVisible =
                false;

            c.notesRequired =
                false;

        };


    // =========================================================
    // NOTES VISIBILITY
    //
    // Requested -> hidden
    // Approved  -> hidden
    // Rejected  -> visible + required
    // =========================================================

    c.updateNotesVisibility =
        function() {

            var approval =
                String(
                    c.selectedRecord &&
                    c.selectedRecord.approval
                        ? c.selectedRecord.approval
                        : ''
                ).toLowerCase();


            if (
                approval === 'rejected'
            ) {

                c.notesVisible =
                    true;

                c.notesRequired =
                    true;

            } else {

                c.notesVisible =
                    false;

                c.notesRequired =
                    false;

            }

        };


    // =========================================================
    // SAVE RECORD
    // =========================================================

    c.saveRecord =
        function() {

            c.formError =
                '';

            c.formSuccess =
                '';


            if (
                !c.selectedRecord ||
                !c.selectedRecord.sys_id
            ) {

                c.formError =
                    'Invalid record selected.';

                return;

            }


            var approval =
                String(
                    c.selectedRecord.approval || ''
                ).toLowerCase();


            // -----------------------------------------------
            // VALID APPROVAL
            // -----------------------------------------------

            if (
                approval !== 'requested' &&
                approval !== 'approved' &&
                approval !== 'rejected'
            ) {

                c.formError =
                    'Please select a valid approval status.';

                return;

            }


            // -----------------------------------------------
            // REJECTED REQUIRES NOTES
            // -----------------------------------------------

            if (
                approval === 'rejected' &&
                !String(
                    c.selectedRecord.notes || ''
                ).trim()
            ) {

                c.formError =
                    'Notes are required when rejecting a record.';

                return;

            }


            c.savingRecord =
                true;


            c.server.get({

                action:
                    'saveRecord',

                sys_id:
                    c.selectedRecord.sys_id,

                approval:
                    approval,

                notes:
                    c.selectedRecord.notes || ''

            }).then(
                function(response) {

                    c.savingRecord =
                        false;


                    if (
                        response.data.saveSuccess
                    ) {

                        c.formSuccess =
                            'Record updated successfully.';


                        // -----------------------------------
                        // UPDATE LOCAL RECORD
                        // -----------------------------------

                        var sysId =
                            c.selectedRecord.sys_id;


                        if (
                            c.data.records[sysId]
                        ) {

                            c.data.records[
                                sysId
                            ].approval =
                                approval;


                            c.data.records[
                                sysId
                            ].approval_display =
                                approval;


                            c.data.records[
                                sysId
                            ].notes =
                                c.selectedRecord.notes || '';


                            if (
                                approval === 'approved' ||
                                approval === 'rejected'
                            ) {

                                c.data.records[
                                    sysId
                                ].active =
                                    'false';

                            }

                        }


                        // -----------------------------------
                        // REMOVE FROM REQUESTED ASSIGNMENTS
                        // -----------------------------------

                        c.data.myAssignmentIds =
                            c.data.myAssignmentIds.filter(
                                function(id) {

                                    var record =
                                        c.data.records[id];


                                    return (
                                        record &&
                                        String(
                                            record.approval
                                        ).toLowerCase() ===
                                        'requested'
                                    );

                                }
                            );


                        // -----------------------------------
                        // RECENT ASSIGNMENTS
                        // -----------------------------------

                        c.data.recentAssignmentIds =
                            c.data.myAssignmentIds.slice(
                                0,
                                5
                            );


                        // -----------------------------------
                        // FILTERED ASSIGNMENTS
                        // -----------------------------------

                        c.applyAssignmentFilters();


                        // -----------------------------------
                        // CLOSE FORM
                        // -----------------------------------

                        setTimeout(
                            function() {

                                c.closeRecordForm();

                                $scope.$apply();

                            },
                            500
                        );


                    } else {

                        c.formError =
                            response.data.saveError ||
                            'Unable to update the record.';

                    }

                }
            );

        };


    // =========================================================
    // BAR CHART WIDTH
    // =========================================================

    c.getBarWidth =
        function(
            value,
            list
        ) {

            if (
                !list ||
                list.length === 0
            ) {

                return 0;

            }


            var max =
                0;


            for (
                var i = 0;
                i < list.length;
                i++
            ) {

                var current =
                    parseInt(
                        list[i].total,
                        10
                    ) || 0;


                if (
                    current > max
                ) {

                    max =
                        current;

                }

            }


            if (
                max === 0
            ) {

                return 0;

            }


            return (
                (
                    parseInt(
                        value,
                        10
                    ) / max
                ) * 100
            );

        };


    // =========================================================
    // TIME CHART HEIGHT
    // =========================================================

    c.getTimeBarHeight =
        function(
            value,
            list
        ) {

            if (
                !list ||
                list.length === 0
            ) {

                return 0;

            }


            var max =
                0;


            for (
                var i = 0;
                i < list.length;
                i++
            ) {

                var current =
                    parseInt(
                        list[i].total,
                        10
                    ) || 0;


                if (
                    current > max
                ) {

                    max =
                        current;

                }

            }


            if (
                max === 0
            ) {

                return 0;

            }


            return (
                (
                    parseInt(
                        value,
                        10
                    ) / max
                ) * 100
            );

        };

};

sp_widget.css:
/* ==========================================
   MAIN LAYOUT
   ========================================== */

.manager-dashboard {
    display: flex;
    min-height: 100vh;
    background: #f5f6f8;
    color: #2d3748;
    font-family: Arial, Helvetica, sans-serif;
}


/* ==========================================
   SIDEBAR
   ========================================== */

.manager-sidebar {
    width: 230px;
    min-width: 230px;
    background: #ffffff;
    border-right: 1px solid #e5e7eb;
    padding: 20px 12px;
}

.sidebar-title {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 17px;
    font-weight: 600;
    padding: 10px 12px 25px;
    color: #263238;
}

.sidebar-icon {
    font-size: 20px;
}

.sidebar-menu {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.menu-item {
    width: 100%;
    border: none;
    background: transparent;
    text-align: left;
    padding: 12px 14px;
    border-radius: 5px;
    cursor: pointer;
    color: #4b5563;
    font-size: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.menu-item:hover {
    background: #f3f4f6;
}

.menu-item.active {
    background: #e8f1fb;
    color: #1f5f99;
    font-weight: 600;
}


/* ==========================================
   MAIN CONTENT
   ========================================== */

.manager-main {
    flex: 1;
    padding: 25px;
    min-width: 0;
}

.page-header {
    margin-bottom: 22px;
}

.page-header h2 {
    margin: 0 0 5px;
    font-size: 24px;
    font-weight: 600;
    color: #263238;
}

.page-header p {
    margin: 0;
    color: #6b7280;
    font-size: 14px;
}


/* ==========================================
   KPI CARDS
   ========================================== */

.kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.kpi-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 20px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

.kpi-title {
    color: #6b7280;
    font-size: 14px;
    margin-bottom: 10px;
}

.kpi-value {
    font-size: 30px;
    font-weight: 600;
    color: #263238;
}

.kpi-subtitle {
    color: #9ca3af;
    font-size: 12px;
    margin-top: 5px;
}


/* ==========================================
   SECTION CARD
   ========================================== */

.section-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    margin-bottom: 20px;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 18px 20px;
    border-bottom: 1px solid #e5e7eb;
}

.section-header h3 {
    margin: 0 0 4px;
    font-size: 17px;
    font-weight: 600;
}

.section-header p {
    margin: 0;
    font-size: 13px;
    color: #6b7280;
}

.record-count {
    color: #6b7280;
    font-size: 13px;
}


/* ==========================================
   TABLE
   ========================================== */

.table-container {
    width: 100%;
    overflow-x: auto;
}

.standard-table {
    width: 100%;
    border-collapse: collapse;
}

.standard-table th {
    background: #f8f9fa;
    color: #4b5563;
    font-size: 12px;
    font-weight: 600;
    text-align: left;
    padding: 12px 15px;
    border-bottom: 1px solid #e5e7eb;
    white-space: nowrap;
}

.standard-table td {
    padding: 13px 15px;
    border-bottom: 1px solid #edf0f2;
    font-size: 13px;
    color: #374151;
    vertical-align: middle;
}

.standard-table tbody tr:hover {
    background: #fafafa;
}

.empty-message {
    text-align: center !important;
    color: #9ca3af !important;
    padding: 30px !important;
}


/* ==========================================
   BUTTONS
   ========================================== */

.primary-button,
.secondary-button,
.open-button,
.clear-button {
    border-radius: 4px;
    padding: 8px 14px;
    font-size: 13px;
    cursor: pointer;
}

.primary-button {
    background: #1f5f99;
    color: #ffffff;
    border: 1px solid #1f5f99;
}

.primary-button:hover {
    background: #174b7a;
}

.primary-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.secondary-button {
    background: #ffffff;
    border: 1px solid #d1d5db;
    color: #374151;
}

.secondary-button:hover {
    background: #f9fafb;
}

.open-button {
    background: #ffffff;
    color: #1f5f99;
    border: 1px solid #1f5f99;
}

.open-button:hover {
    background: #eef5fb;
}

.clear-button {
    background: #ffffff;
    border: 1px solid #d1d5db;
    color: #4b5563;
}

.clear-button:hover {
    background: #f9fafb;
}


/* ==========================================
   FILTERS
   ========================================== */

.filter-card {
    display: flex;
    align-items: flex-end;
    gap: 15px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 18px;
    margin-bottom: 20px;
}

.filter-group {
    width: 250px;
}

.filter-group label,
.form-field label {
    display: block;
    font-size: 12px;
    font-weight: 600;
    color: #4b5563;
    margin-bottom: 6px;
}

.form-control {
    width: 100%;
    min-height: 36px;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    padding: 7px 9px;
    background: #ffffff;
    color: #374151;
    font-size: 13px;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #1f5f99;
    box-shadow: 0 0 0 1px #1f5f99;
}

textarea.form-control {
    min-height: 80px;
    resize: vertical;
}


/* ==========================================
   REPORTS
   ========================================== */

.reports-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

.report-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 20px;
    min-height: 320px;
}

.report-wide {
    grid-column: 1 / 3;
}

.report-header {
    margin-bottom: 22px;
}

.report-header h3 {
    margin: 0 0 5px;
    font-size: 17px;
    font-weight: 600;
    color: #263238;
}

.report-header p {
    margin: 0;
    font-size: 12px;
    color: #6b7280;
}


/* ==========================================
   BAR CHART
   ========================================== */

.simple-bar-chart {
    display: flex;
    flex-direction: column;
    gap: 13px;
}

.bar-row {
    display: grid;
    grid-template-columns: 180px 1fr 45px;
    align-items: center;
    gap: 10px;
}

.bar-label {
    font-size: 12px;
    color: #4b5563;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.bar-track {
    height: 18px;
    background: #eef1f4;
    border-radius: 3px;
    overflow: hidden;
}

.bar-fill {
    height: 100%;
    background: #5b8db8;
    border-radius: 3px;
    min-width: 2px;
    transition: width 0.3s ease;
}

.bar-value {
    text-align: right;
    font-size: 12px;
    font-weight: 600;
    color: #374151;
}


/* ==========================================
   APPROVAL REPORT
   ========================================== */

.approval-chart {
    display: flex;
    justify-content: space-around;
    align-items: center;
    min-height: 200px;
    gap: 15px;
}

.approval-item {
    text-align: center;
}

.approval-circle {
    width: 85px;
    height: 85px;
    border-radius: 50%;
    border: 7px solid #dbe5ee;
    display: flex;
    justify-content: center;
    align-items: center;
    margin: 0 auto 10px;
    font-size: 19px;
    font-weight: 600;
    color: #374151;
}

.approval-info strong {
    display: block;
    font-size: 13px;
    color: #374151;
}

.approval-info span {
    display: block;
    margin-top: 4px;
    font-size: 11px;
    color: #9ca3af;
}


/* ==========================================
   TIME CHART
   ========================================== */

.time-chart {
    height: 230px;
    display: flex;
    align-items: flex-end;
    gap: 25px;
    padding: 10px 15px 0;
    border-bottom: 1px solid #dfe3e7;
    overflow-x: auto;
}

.time-column {
    min-width: 55px;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-items: center;
}

.time-value {
    font-size: 11px;
    font-weight: 600;
    color: #374151;
    margin-bottom: 5px;
}

.time-bar-area {
    width: 34px;
    height: 160px;
    display: flex;
    align-items: flex-end;
}

.time-bar {
    width: 100%;
    background: #5b8db8;
    border-radius: 3px 3px 0 0;
    min-height: 3px;
}

.time-label {
    font-size: 11px;
    color: #6b7280;
    margin-top: 8px;
    white-space: nowrap;
}


/* ==========================================
   RECORD MODAL
   ========================================== */

.record-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.35);
    z-index: 9999;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 25px;
}

.record-modal {
    width: 900px;
    max-width: 100%;
    max-height: 92vh;
    background: #ffffff;
    border-radius: 6px;
    display: flex;
    flex-direction: column;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.record-modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 18px 22px;
    border-bottom: 1px solid #e5e7eb;
}

.record-modal-header h3 {
    margin: 0 0 4px;
    font-size: 18px;
}

.record-modal-header p {
    margin: 0;
    font-size: 12px;
    color: #6b7280;
}

.close-button {
    border: none;
    background: transparent;
    font-size: 25px;
    color: #6b7280;
    cursor: pointer;
}

.close-button:hover {
    color: #111827;
}

.record-modal-body {
    padding: 22px;
    overflow-y: auto;
}

.record-modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 15px 22px;
    border-top: 1px solid #e5e7eb;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 15px;
    margin-bottom: 15px;
}

.form-field {
    margin-bottom: 15px;
}

.required-star {
    color: #d9534f;
}


/* ==========================================
   ALERTS
   ========================================== */

.alert {
    padding: 10px 12px;
    border-radius: 4px;
    margin-top: 10px;
    font-size: 13px;
}

.alert-danger {
    background: #fdf0f0;
    border: 1px solid #f2caca;
    color: #a94442;
}

.alert-success {
    background: #eff8f0;
    border: 1px solid #cde6cf;
    color: #3c763d;
}


/* ==========================================
   RESPONSIVE
   ========================================== */

@media (max-width: 900px) {

    .manager-sidebar {
        width: 190px;
        min-width: 190px;
    }

    .kpi-grid {
        grid-template-columns: 1fr;
    }

    .reports-grid {
        grid-template-columns: 1fr;
    }

    .report-wide {
        grid-column: auto;
    }

    .bar-row {
        grid-template-columns: 120px 1fr 40px;
    }

}

@media (max-width: 700px) {

    .manager-dashboard {
        flex-direction: column;
    }

    .manager-sidebar {
        width: 100%;
        min-width: 100%;
        border-right: none;
        border-bottom: 1px solid #e5e7eb;
    }

    .sidebar-menu {
        flex-direction: row;
        overflow-x: auto;
    }

    .menu-item {
        width: auto;
        white-space: nowrap;
    }

    .manager-main {
        padding: 15px;
    }

    .filter-card {
        flex-direction: column;
        align-items: stretch;
    }

    .filter-group {
        width: 100%;
    }

    .form-row {
        grid-template-columns: 1fr;
    }

}

sp_widget.script:
(function() {

    // =========================================================
    // INITIAL DATA
    // =========================================================

    data.totalRequests = 0;
    data.pendingProblems = 0;
    data.resolvedRequests = 0;

    data.records = {};

    data.myAssignmentIds = [];
    data.recentAssignmentIds = [];
    data.historyIds = [];

    data.filterOptions = {
        useCases: [],
        priorities: []
    };

    data.reports = {
        useCase: [],
        priority: [],
        approval: [],
        overTime: []
    };


    // =========================================================
    // CONSTANTS
    // =========================================================

    var managerGroup =
        '1754d95bdd1f03107f44143a6accf85b';

    var taskTable =
        'x_snc_campus_foo_1_complain_tasks';

    var complaintTable =
        'x_snc_campus_foo_1_food_complaint';


    // =========================================================
    // KPI 1
    // TOTAL REQUESTS
    //
    // FOOD COMPLAINT
    // COUNT ALL RECORDS
    // =========================================================

    var totalGR =
        new GlideAggregate(complaintTable);

    totalGR.addAggregate('COUNT');

    totalGR.query();

    if (totalGR.next()) {

        data.totalRequests =
            parseInt(
                totalGR.getAggregate('COUNT'),
                10
            ) || 0;

    }


    // =========================================================
    // KPI 3
    // RESOLVED REQUESTS
    //
    // FOOD COMPLAINT
    // state = closed
    // =========================================================

    var resolvedGR =
        new GlideAggregate(complaintTable);

    resolvedGR.addQuery(
        'state',
        'closed'
    );

    resolvedGR.addAggregate('COUNT');

    resolvedGR.query();

    if (resolvedGR.next()) {

        data.resolvedRequests =
            parseInt(
                resolvedGR.getAggregate('COUNT'),
                10
            ) || 0;

    }


    // =========================================================
    // USE CASE CHOICES
    //
    // sys_choice
    // =========================================================

    var choiceGR =
        new GlideRecord('sys_choice');

    choiceGR.addQuery(
        'name',
        taskTable
    );

    choiceGR.addQuery(
        'element',
        'use_case'
    );

    choiceGR.addQuery(
        'inactive',
        false
    );

    choiceGR.addQuery(
        'language',
        'en'
    );

    choiceGR.orderBy('sequence');

    choiceGR.query();

    while (choiceGR.next()) {

        data.filterOptions.useCases.push({

            value:
                choiceGR.getValue('value'),

            label:
                choiceGR.getValue('label')

        });

    }


    // =========================================================
    // CURRENT PRIORITY CHOICES
    //
    // Critical = 1
    // High     = 2
    // Medium   = 3
    // Low      = 4
    // =========================================================

    var priorityChoiceGR =
        new GlideRecord('sys_choice');

    priorityChoiceGR.addQuery(
        'name',
        taskTable
    );

    priorityChoiceGR.addQuery(
        'element',
        'current_priority'
    );

    priorityChoiceGR.addQuery(
        'inactive',
        false
    );

    priorityChoiceGR.addQuery(
        'language',
        'en'
    );

    priorityChoiceGR.orderBy('sequence');

    priorityChoiceGR.query();

    while (priorityChoiceGR.next()) {

        data.filterOptions.priorities.push({

            value:
                priorityChoiceGR.getValue('value'),

            label:
                priorityChoiceGR.getValue('label')

        });

    }


    // =========================================================
    // REPORT TEMPORARY DATA
    // =========================================================

    var useCaseTotals = {};
    var priorityTotals = {};
    var approvalTotals = {};
    var monthTotals = {};


    // =========================================================
    // ONE QUERY FOR COMPLAINT TASKS
    //
    // Used for:
    // 1. data.records
    // 2. Manager assignments
    // 3. History
    // 4. Reports
    //
    // Reports use ALL records.
    // =========================================================

    var taskGR =
        new GlideRecord(taskTable);

    taskGR.orderByDesc(
        'sys_created_on'
    );

    taskGR.query();


    while (taskGR.next()) {

        var sysId =
            taskGR.getUniqueValue();


        // =====================================================
        // APPROVAL
        // =====================================================

        var approvalValue =
            String(
                taskGR.getValue('approval') || ''
            ).toLowerCase();


        var approvalLabel =
            taskGR.getDisplayValue(
                'approval'
            ) ||
            approvalValue ||
            'Not Set';


        // =====================================================
        // STUDENT COUNT
        // =====================================================

        var studentCount =
            parseInt(
                taskGR.getValue('student_count'),
                10
            ) || 0;


        // =====================================================
        // USE CASE
        // =====================================================

        var useCaseValue =
            taskGR.getValue(
                'use_case'
            ) || '';


        var useCaseLabel =
            taskGR.getDisplayValue(
                'use_case'
            ) || 'Not Set';


        // =====================================================
        // CURRENT PRIORITY
        // =====================================================

        var priorityValue =
            taskGR.getValue(
                'current_priority'
            ) || '';


        var priorityLabel =
            taskGR.getDisplayValue(
                'current_priority'
            ) || 'Not Set';


        // =====================================================
        // STORE COMPLETE RECORD
        // =====================================================

        data.records[sysId] = {

            // -------------------------------
            // IDENTIFICATION
            // -------------------------------

            sys_id:
                sysId,

            number:
                taskGR.getDisplayValue(
                    'number'
                ),


            // -------------------------------
            // COMPLAINT INFORMATION
            // -------------------------------

            use_case_value:
                useCaseValue,

            use_case:
                useCaseLabel,

            problem_type:
                taskGR.getValue(
                    'problem_type'
                ),

            meal_type:
                taskGR.getDisplayValue(
                    'meal_type'
                ),

            short_description:
                taskGR.getValue(
                    'short_description'
                ),

            description:
                taskGR.getValue(
                    'description'
                ),

            notes:
                taskGR.getValue(
                    'notes'
                ),

            student_count:
                taskGR.getDisplayValue(
                    'student_count'
                ),

            use_case_number:
                taskGR.getValue(
                    'use_case_number'
                ),


            // -------------------------------
            // PRIORITY
            // -------------------------------

            current_priority_value:
                priorityValue,

            current_priority:
                priorityLabel,

            priority_reason:
                taskGR.getValue(
                    'priority_reason'
                ),


            // -------------------------------
            // ASSIGNMENT
            // -------------------------------

            assigned_to:
                taskGR.getDisplayValue(
                    'assigned_to'
                ),

            assignment_group:
                taskGR.getDisplayValue(
                    'assignment_group'
                ),

            assignment_group_value:
                taskGR.getValue(
                    'assignment_group'
                ),


            // -------------------------------
            // APPROVAL / WORKFLOW
            // -------------------------------

            approval:
                approvalValue,

            approval_display:
                approvalLabel,

            active:
                taskGR.getValue(
                    'active'
                ),


            // -------------------------------
            // RESOLUTION
            // -------------------------------

            recomended_actions:
                taskGR.getValue(
                    'recomended_actions'
                ),


            // -------------------------------
            // ACTIVITY
            // -------------------------------

            comments:
                taskGR.getValue(
                    'comments'
                ),

            work_notes:
                taskGR.getValue(
                    'work_notes'
                ),


            // -------------------------------
            // DATE / TIME
            // -------------------------------

            due_date:
                taskGR.getDisplayValue(
                    'due_date'
                ),

            opened_at:
                taskGR.getDisplayValue(
                    'opened_at'
                ),

            sys_created_on:
                taskGR.getDisplayValue(
                    'sys_created_on'
                ),

            closed_at:
                taskGR.getDisplayValue(
                    'closed_at'
                ),


            // -------------------------------
            // USERS
            // -------------------------------

            opened_by:
                taskGR.getDisplayValue(
                    'opened_by'
                ),

            closed_by:
                taskGR.getDisplayValue(
                    'closed_by'
                )

        };


        // =====================================================
        // REPORT 1
        // REQUESTS BY USE CASE
        //
        // SUM(student_count)
        // =====================================================

        if (!useCaseTotals[useCaseValue]) {

            useCaseTotals[useCaseValue] = {

                label:
                    useCaseLabel,

                total:
                    0

            };

        }

        useCaseTotals[useCaseValue].total +=
            studentCount;


        // =====================================================
        // REPORT 2
        // REQUESTS BY PRIORITY
        //
        // SUM(student_count)
        // =====================================================

        if (!priorityTotals[priorityValue]) {

            priorityTotals[priorityValue] = {

                label:
                    priorityLabel,

                total:
                    0

            };

        }

        priorityTotals[priorityValue].total +=
            studentCount;


        // =====================================================
        // REPORT 3
        // APPROVAL STATUS
        //
        // SUM(student_count)
        // =====================================================

        if (!approvalTotals[approvalValue]) {

            approvalTotals[approvalValue] = {

                label:
                    approvalLabel,

                total:
                    0

            };

        }

        approvalTotals[approvalValue].total +=
            studentCount;


        // =====================================================
        // REPORT 4
        // REQUESTS OVER TIME
        //
        // sys_created_on
        // GROUP BY MONTH
        // SUM(student_count)
        // =====================================================

        var createdDate =
            taskGR.getValue(
                'sys_created_on'
            );


        if (createdDate) {

            var monthKey =
                createdDate.substring(
                    0,
                    7
                );


            var monthLabel =
                createdDate.substring(
                    0,
                    7
                );


            if (!monthTotals[monthKey]) {

                monthTotals[monthKey] = {

                    label:
                        monthLabel,

                    total:
                        0

                };

            }


            monthTotals[monthKey].total +=
                studentCount;

        }


        // =====================================================
        // MANAGER ASSIGNMENTS
        //
        // assignment_group = MANAGER GROUP
        // approval = requested
        // =====================================================

        var assignmentGroupValue =
            taskGR.getValue(
                'assignment_group'
            );


        if (
            assignmentGroupValue === managerGroup &&
            approvalValue === 'requested'
        ) {

            data.myAssignmentIds.push(
                sysId
            );

        }


        // =====================================================
        // HISTORY
        //
        // MANAGER GROUP
        // approval = approved OR rejected
        // =====================================================

        if (
            assignmentGroupValue === managerGroup &&
            (
                approvalValue === 'approved' ||
                approvalValue === 'rejected'
            )
        ) {

            data.historyIds.push(
                sysId
            );

        }

    }


    // =========================================================
    // PENDING PROBLEMS
    //
    // ALL COMPLAINT TASKS
    // approval = requested
    // =========================================================

    var pendingGR =
        new GlideAggregate(taskTable);

    pendingGR.addQuery(
        'approval',
        'requested'
    );

    pendingGR.addAggregate(
        'COUNT'
    );

    pendingGR.query();


    if (pendingGR.next()) {

        data.pendingProblems =
            parseInt(
                pendingGR.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;

    }


    // =========================================================
    // TOP 5 RECENT MANAGER ASSIGNMENTS
    // =========================================================

    for (
        var i = 0;
        i < data.myAssignmentIds.length &&
        i < 5;
        i++
    ) {

        data.recentAssignmentIds.push(
            data.myAssignmentIds[i]
        );

    }


    // =========================================================
    // USE CASE REPORT
    // =========================================================

    for (
        var useCaseKey in useCaseTotals
    ) {

        data.reports.useCase.push({

            label:
                useCaseTotals[
                    useCaseKey
                ].label,

            total:
                useCaseTotals[
                    useCaseKey
                ].total

        });

    }


    // =========================================================
    // PRIORITY REPORT
    // =========================================================

    for (
        var priorityKey in priorityTotals
    ) {

        data.reports.priority.push({

            label:
                priorityTotals[
                    priorityKey
                ].label,

            total:
                priorityTotals[
                    priorityKey
                ].total

        });

    }


    // =========================================================
    // APPROVAL REPORT
    // =========================================================

    for (
        var approvalKey in approvalTotals
    ) {

        data.reports.approval.push({

            label:
                approvalTotals[
                    approvalKey
                ].label,

            total:
                approvalTotals[
                    approvalKey
                ].total

        });

    }


    // =========================================================
    // OVER TIME REPORT
    // =========================================================

    var monthKeys = [];


    for (
        var monthKeyValue in monthTotals
    ) {

        monthKeys.push(
            monthKeyValue
        );

    }


    monthKeys.sort();


    for (
        var m = 0;
        m < monthKeys.length;
        m++
    ) {

        var currentMonth =
            monthKeys[m];


        data.reports.overTime.push({

            label:
                monthTotals[
                    currentMonth
                ].label,

            total:
                monthTotals[
                    currentMonth
                ].total

        });

    }


    // =========================================================
    // UPDATE EXISTING RECORD
    //
    // IMPORTANT:
    // This does NOT INSERT a new record.
    // It updates the existing record using sys_id.
    // =========================================================

    if (
        input &&
        input.action === 'saveRecord' &&
        input.sys_id
    ) {

        var updateGR =
            new GlideRecord(taskTable);


        if (
            updateGR.get(
                input.sys_id
            )
        ) {

            var newApproval =
                String(
                    input.approval || ''
                ).toLowerCase();


            // -----------------------------------------------
            // APPROVAL
            // -----------------------------------------------

            updateGR.setValue(
                'approval',
                newApproval
            );


            // -----------------------------------------------
            // NOTES
            // -----------------------------------------------

            updateGR.setValue(
                'notes',
                input.notes || ''
            );


            // -----------------------------------------------
            // APPROVED
            // -----------------------------------------------

            if (
                newApproval === 'approved'
            ) {

                updateGR.setValue(
                    'active',
                    false
                );

                updateGR.setValue(
                    'closed_at',
                    new GlideDateTime()
                );

                updateGR.setValue(
                    'closed_by',
                    gs.getUserID()
                );

            }


            // -----------------------------------------------
            // REJECTED
            // -----------------------------------------------

            if (
                newApproval === 'rejected'
            ) {

                updateGR.setValue(
                    'active',
                    false
                );

                updateGR.setValue(
                    'closed_at',
                    new GlideDateTime()
                );

                updateGR.setValue(
                    'closed_by',
                    gs.getUserID()
                );

            }


            updateGR.update();

            data.saveSuccess = true;

        } else {

            data.saveSuccess = false;

            data.saveError =
                'Unable to find the selected record.';

        }

    }

})();
